/* @autogenerated */
import { BehaviorSubject, of } from 'rxjs';
import { IdentityService } from './identity.service';
import { IdentityHandler, IdentityProvider } from './identity-provider.interface';
import { AppConfigService } from '@shared/context/config/app-config.service';

describe('IdentityService', () => {
  it('selects handler based on identity config and delegates actions', () => {
    const handler: IdentityHandler = {
      bootstrap: jasmine.createSpy('bootstrap').and.returnValue(of(undefined)),
      login: jasmine.createSpy('login'),
      logout: jasmine.createSpy('logout'),
    };

    const provider: IdentityProvider = {
      accept: (type) => (type === 'oidc' ? handler : null),
    };

    const identity$ = new BehaviorSubject({
      main: { type: 'oidc' },
    });
    const appConfig = { identity: identity$.asObservable() } as unknown as AppConfigService;

    const service = new IdentityService(appConfig, [provider]);

    service.bootstrap('main').subscribe();
    service.login('main');
    service.logout('main');

    expect(handler.bootstrap).toHaveBeenCalled();
    expect(handler.login).toHaveBeenCalled();
    expect(handler.logout).toHaveBeenCalled();
  });

  it('logs error when multiple providers match the same identity type', () => {
    spyOn(console, 'error');
    const handler: IdentityHandler = {
      bootstrap: jasmine.createSpy('bootstrap').and.returnValue(of(undefined)),
      login: jasmine.createSpy('login'),
      logout: jasmine.createSpy('logout'),
    };
    const provider1: IdentityProvider = { accept: () => handler };
    const provider2: IdentityProvider = { accept: () => handler };

    const identity$ = new BehaviorSubject({ main: { type: 'oidc' } });
    const appConfig = { identity: identity$.asObservable() } as unknown as AppConfigService;

    new IdentityService(appConfig, [provider1, provider2]);

    expect(console.error).toHaveBeenCalledWith(jasmine.stringContaining('Hay más de un manager'));
  });

  it('logs error when no provider matches the identity type', () => {
    spyOn(console, 'error');
    const provider: IdentityProvider = { accept: () => null };

    const identity$ = new BehaviorSubject({ main: { type: 'unknown-type' } });
    const appConfig = { identity: identity$.asObservable() } as unknown as AppConfigService;

    new IdentityService(appConfig, [provider]);

    expect(console.error).toHaveBeenCalledWith(jasmine.stringContaining('No hay un manager'));
  });

  it('login is a no-op when the key is not in the map', () => {
    const identity$ = new BehaviorSubject({});
    const appConfig = { identity: identity$.asObservable() } as unknown as AppConfigService;
    const service = new IdentityService(appConfig, []);

    expect(() => service.login('nonexistent')).not.toThrow();
  });

  it('logout is a no-op when the key is not in the map', () => {
    const identity$ = new BehaviorSubject({});
    const appConfig = { identity: identity$.asObservable() } as unknown as AppConfigService;
    const service = new IdentityService(appConfig, []);

    expect(() => service.logout('nonexistent')).not.toThrow();
  });
});
